draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30 + 10 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30 + 10 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 130);
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 40 + 20 * Math.sin(t), H/2 - 30, 20, 10);

  // progress bar
  ctx.fillStyle = 'black';
  ctx.fillRect(10, 10, 100 * (0.5 + 0.5 * Math.sin(t)), 10);

  ctx.restore();
}
